ALTER TABLE equipment ADD COLUMN revision INTEGER NOT NULL DEFAULT 0 CHECK(revision>=0);
UPDATE equipment SET revision=coalesce((SELECT max(version) FROM entity_versions WHERE entity_id=equipment.id),0);
ALTER TABLE equipment ADD COLUMN asset_key TEXT;
UPDATE equipment SET asset_key=qr_token;
ALTER TABLE equipment ADD COLUMN purchased_on TEXT;
ALTER TABLE equipment ADD COLUMN life_due_override TEXT;
ALTER TABLE equipment ADD COLUMN maintenance_due_override TEXT;
ALTER TABLE equipment ADD COLUMN maintenance_interval_days INTEGER CHECK(maintenance_interval_days IS NULL OR (maintenance_interval_days>0 AND maintenance_interval_months IS NULL));
CREATE INDEX equipment_asset_key ON equipment(asset_key);
CREATE TRIGGER equipment_identity_locked BEFORE UPDATE OF id,building_id,qr_token,asset_key ON equipment WHEN NEW.id<>OLD.id OR NEW.building_id<>OLD.building_id OR NEW.qr_token<>OLD.qr_token OR (OLD.asset_key IS NOT NULL AND NEW.asset_key IS NOT OLD.asset_key) BEGIN SELECT RAISE(ABORT,'Equipment identity is immutable'); END;
CREATE TABLE equipment_photos(equipment_id TEXT NOT NULL REFERENCES equipment(id),file_id TEXT NOT NULL REFERENCES files(id),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),PRIMARY KEY(equipment_id,file_id)) STRICT;
CREATE UNIQUE INDEX location_unique_name ON locations(building_id,coalesce(parent_id,''),kind,lower(name));
INSERT INTO permissions VALUES('inventory.cost.read');
INSERT INTO role_permissions SELECT code,'inventory.cost.read' FROM roles WHERE code IN('exploitant','technique','securite');
INSERT INTO role_permissions VALUES('commission','inventory.read');
ALTER TABLE consumption_readings RENAME TO consumption_readings_legacy;
CREATE TABLE consumption_readings(id TEXT PRIMARY KEY,equipment_id TEXT NOT NULL REFERENCES equipment(id),measured_at TEXT NOT NULL,quantity_milliunits INTEGER NOT NULL CHECK(quantity_milliunits>=0),unit TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN('cumulative','interval')),period_start TEXT,recorded_by TEXT NOT NULL REFERENCES users(id),reset INTEGER NOT NULL DEFAULT 0 CHECK(reset IN(0,1) AND (reset=0 OR mode='cumulative'))) STRICT;
INSERT INTO consumption_readings(id,equipment_id,measured_at,quantity_milliunits,unit,mode,period_start,recorded_by) SELECT id,equipment_id,measured_at,quantity_milliunits,unit,mode,period_start,recorded_by FROM consumption_readings_legacy;
DROP TABLE consumption_readings_legacy;
CREATE INDEX idx_consumption ON consumption_readings(equipment_id,measured_at);
CREATE TABLE consumption_cancellations(reading_id TEXT PRIMARY KEY REFERENCES consumption_readings(id),recorded_at TEXT NOT NULL,recorded_by TEXT NOT NULL REFERENCES users(id),reason TEXT NOT NULL) STRICT;
CREATE TRIGGER reading_active_unique BEFORE INSERT ON consumption_readings WHEN NOT EXISTS(SELECT 1 FROM consumption_cancellations WHERE reading_id=NEW.id) AND EXISTS(SELECT 1 FROM consumption_readings r WHERE r.equipment_id=NEW.equipment_id AND r.measured_at=NEW.measured_at AND r.unit=NEW.unit AND r.mode=NEW.mode AND NOT EXISTS(SELECT 1 FROM consumption_cancellations WHERE reading_id=r.id)) BEGIN SELECT RAISE(ABORT,'An active reading already exists'); END;
CREATE TRIGGER readings_no_update BEFORE UPDATE ON consumption_readings BEGIN SELECT RAISE(ABORT,'Readings are append-only'); END;
CREATE TRIGGER readings_no_delete BEFORE DELETE ON consumption_readings BEGIN SELECT RAISE(ABORT,'Readings are append-only'); END;
CREATE TRIGGER cancellations_no_update BEFORE UPDATE ON consumption_cancellations BEGIN SELECT RAISE(ABORT,'Cancellations are append-only'); END;
CREATE TRIGGER cancellations_no_delete BEFORE DELETE ON consumption_cancellations BEGIN SELECT RAISE(ABORT,'Cancellations are append-only'); END;
